const store = this.getWorkflowStaticData('global');
if (!Array.isArray(store.transactions)) store.transactions = [];
if (!store.failedById || typeof store.failedById !== 'object') store.failedById = {};
if (!store.replayById || typeof store.replayById !== 'object') store.replayById = {};

const tx = $json || {};
if (!tx.execution_id) {
  return [{ json: { status: 'IGNORED', reason: 'missing execution_id' } }];
}

const existingIndex = store.transactions.findIndex((row) => row.execution_id === tx.execution_id);
if (existingIndex >= 0) {
  store.transactions[existingIndex] = tx;
} else {
  store.transactions.push(tx);
}

if (store.transactions.length > 10000) {
  store.transactions = store.transactions.slice(-10000);
}

if (tx.status === 'FAILED') {
  store.failedById[tx.execution_id] = tx;
  store.replayById[tx.execution_id] = {
    execution_id: tx.execution_id,
    source: 'cockpit-log',
    original_request: tx.payload_snapshot?.original_request || null,
    transaction: tx
  };
}

if (tx.status === 'SUCCESS' && store.failedById[tx.execution_id]) {
  delete store.failedById[tx.execution_id];
}

return [{
  json: {
    status: 'LOGGED',
    execution_id: tx.execution_id,
    total_transactions: store.transactions.length
  }
}];

const store = this.getWorkflowStaticData('global');
if (!store.failedById || typeof store.failedById !== 'object') store.failedById = {};
if (!store.replayById || typeof store.replayById !== 'object') store.replayById = {};
if (!Array.isArray(store.transactions)) store.transactions = [];

const incoming = $json || {};
const executionId = incoming.execution_id || incoming.log?.execution_id || incoming.response?.execution_id;

if (!executionId) {
  return [{ json: { status: 'IGNORED', reason: 'missing execution_id' } }];
}

const failedRecord = {
  execution_id: executionId,
  status: 'FAILED',
  mode: incoming.mode || incoming.log?.mode || incoming.response?.mode || null,
  doctype: incoming.doctype || incoming.log?.doctype || incoming.response?.doctype || null,
  error: incoming.error || incoming.log?.error || incoming.response?.error || 'Unknown failure',
  failed_step: incoming.failed_step || incoming.log?.failed_step || incoming.response?.failed_step || null,
  payload_snapshot: incoming.log?.payload_snapshot || incoming.payload_snapshot || {},
  original_request: incoming.original_request || incoming.log?.payload_snapshot?.original_request || incoming.payload_snapshot?.original_request || null,
  raw: incoming
};

store.failedById[executionId] = failedRecord;
store.replayById[executionId] = failedRecord;

const existingIndex = store.transactions.findIndex((row) => row.execution_id === executionId);
if (existingIndex >= 0) {
  store.transactions[existingIndex] = incoming.log || failedRecord;
} else {
  store.transactions.push(incoming.log || failedRecord);
}

if (store.transactions.length > 10000) {
  store.transactions = store.transactions.slice(-10000);
}

return [{
  json: {
    status: 'FAILED_TX_STORED',
    execution_id: executionId,
    failed_count: Object.keys(store.failedById).length
  }
}];

const store = this.getWorkflowStaticData('global');
const executionId = $json.execution_id;

if (!executionId) {
  return [{
    json: {
      found: false,
      error: 'execution_id is required'
    }
  }];
}

const replayById = store.replayById || {};
const failedById = store.failedById || {};
const transactions = Array.isArray(store.transactions) ? store.transactions : [];

let tx = replayById[executionId] || failedById[executionId] || null;
if (!tx) {
  tx = transactions.find((row) => row.execution_id === executionId) || null;
}

return [{
  json: {
    found: Boolean(tx),
    execution_id: executionId,
    transaction: tx
  }
}];

const store = this.getWorkflowStaticData('global');
const transactions = Array.isArray(store.transactions) ? store.transactions : [];

let successCount = 0;
let failureCount = 0;
let inProgressCount = 0;
let totalDurationMs = 0;
let durationCount = 0;

for (const tx of transactions) {
  if (tx.status === 'SUCCESS') successCount += 1;
  else if (tx.status === 'FAILED') failureCount += 1;
  else if (tx.status === 'IN_PROGRESS') inProgressCount += 1;

  if (tx.start_time && tx.end_time) {
    const start = Date.parse(tx.start_time);
    const end = Date.parse(tx.end_time);
    if (!Number.isNaN(start) && !Number.isNaN(end) && end >= start) {
      totalDurationMs += (end - start);
      durationCount += 1;
    }
  }
}

const avgProcessingTimeMs = durationCount > 0 ? Math.round(totalDurationMs / durationCount) : 0;
const last10 = transactions.slice(-10).reverse();

return [{
  json: {
    generated_at: new Date().toISOString(),
    total_transactions: transactions.length,
    success_count: successCount,
    failure_count: failureCount,
    in_progress_count: inProgressCount,
    avg_processing_time_ms: avgProcessingTimeMs,
    last_10_transactions: last10
  }
}];
